WITH mine AS ( SELECT c.message_id, c.provider_label_id, c.seq, c.label_present_before, (SELECT min(newer.seq) FROM email_gmail_pending_label_writes newer WHERE newer.message_id = c.message_id AND newer.provider_label_id = c.provider_label_id AND newer.seq > c.seq) AS newer_seq, (SELECT older.label_present FROM email_gmail_pending_label_writes older WHERE older.message_id = c.message_id AND older.provider_label_id = c.provider_label_id AND older.seq < c.seq AND older.expires_at > now() ORDER BY older.seq DESC LIMIT 1) AS older_present FROM email_gmail_pending_label_writes c WHERE c.message_id = ANY($1) AND c.write_id = $2 ), inherited AS ( UPDATE email_gmail_pending_label_writes c SET label_present_before = mine.label_present_before FROM mine WHERE c.seq = mine.newer_seq ), removed AS ( DELETE FROM email_gmail_pending_label_writes c USING mine WHERE c.seq = mine.seq ) SELECT message_id AS "message_id!", provider_label_id AS "provider_label_id!", COALESCE(older_present, label_present_before) AS "label_present!" FROM mine WHERE newer_seq IS NULL
